1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	/** The item types the MHPCO will insure, and what each costs to cover. */
29	const BASE_PREMIUMS: Record<string, number | undefined> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	};
36	
37	/** `undefined` for a type the MHPCO does not insure. Rejecting those is not yet specified by a test. */
38	const basePremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];
39	
40	const COMPONENT_BLOCK_SIZE = 3;
41	const COMPONENT_BLOCK_PREMIUM = 60;
42	
43	const countByType = (items: Item[]): Map<string, number> => {
44	  const counts = new Map<string, number>();
45	  for (const item of items) {
46	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
47	  }
48	  return counts;
49	};
50	
51	/** Alike components form a discounted block; everything else is priced per unit. */
52	const basePremiumForGroup = (type: string, count: number): number => {
53	  if (type === "rune" && count === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_PREMIUM;
54	  return count * (basePremiumFor(type) ?? NaN);
55	};
56	
57	const policyBasePremium = (items: Item[]): number => {
58	  let total = 0;
59	  for (const [type, count] of countByType(items)) {
60	    total += basePremiumForGroup(type, count);
61	  }
62	  return total;
63	};
64	
65	const quotePremium = (items: Item[]): number => {
66	  const policyBase = policyBasePremium(items);
67	  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
68	  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
69	  return roundUpToWholeG(withProcessingFee);
70	};
71	
72	export const runScenario = (scenario: Scenario): ScenarioResult => {
73	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
74	};
